import com.kuangsanfeng.ultimategarden.client.function.instant_transmission.debug.TransmissionTickPlan;
public class YRoundingRegression {public static void main(String[] args){var plan=new TransmissionTickPlan();for(int pitch=-90;pitch<=90;pitch+=15)for(int tick=0;tick<40;tick++){var key=plan.next();if(key.pitch()!=pitch||key.tick()!=tick)throw new AssertionError();plan.result(key,tick,true,false);}if(plan.next()!=null||plan.summary().size()!=13)throw new AssertionError();var mismatch=new TransmissionTickPlan();mismatch.result(mismatch.next(),1,true,false);if(mismatch.mismatches()!=1||mismatch.next().tick()!=1)throw new AssertionError();System.out.println("520 tick-plan samples, 13 pitches, late-cast mismatch and no retry passed");}}
